SELECT tmp.*, ( SELECT bc.description FROM hls_bp_category bc WHERE bc.bp_category = tmp.query_bp_category ) query_bp_category_name, ( CASE WHEN tmp.parent_tab_code_flag = 'Y' THEN tmp.tab_code ELSE tmp.parent_table_tab_code END ) form_binder_tab_code FROM ( SELECT t1.LAYOUT_CODE AS layout_code, t1.TAB_CODE AS tab_code, t1.TAB_DESC AS tab_desc, t1.TAB_SEQ AS tab_seq, t1.TAB_GROUP AS tab_group, lower( t1.BASE_TABLE ) AS base_table, t1.QUERY_SOURCE AS query_source, t1.ROW_COUNT AS row_count, t1.COLUMN_COUNT AS column_count, t1.ENABLED_FLAG AS enabled_flag, t1.CREATED_BY AS created_by, t1.CREATION_DATE AS creation_date, t1.LAST_UPDATED_BY AS last_updated_by, t1.LAST_UPDATE_DATE AS last_update_date, t1.CONFIGURABLE AS configurable, t1.FIELD_WIDTH AS field_width, t1.LABEL_WIDTH AS label_width, t1.MARGIN_TOP AS margin_top, t1.BOX_WIDTH AS box_width, t1.SHOW_BOX AS show_box, t1.PARENT_TAB_CODE AS parent_tab_code, t1.PARENT_TABLE AS parent_table, t1.BASE_TABLE_PK AS base_table_pk, t1.flexible, nvl( ( SELECT d.TAB_CODE FROM hls_doc_layout_tab d WHERE d.LAYOUT_CODE = t1.LAYOUT_CODE AND UPPER(d.BASE_TABLE) = UPPER(nvl(t1.PARENT_TABLE, t1.BASE_TABLE )) AND d.TAB_SEQ = ( SELECT min( ht.TAB_SEQ ) FROM hls_doc_layout_tab ht WHERE ht.LAYOUT_CODE = d.LAYOUT_CODE AND ht.BASE_TABLE = d.BASE_TABLE AND ht.ENABLED_FLAG = 'Y' ) AND d.ENABLED_FLAG = 'Y' and rownum=1 ), t1.TAB_CODE ) AS parent_table_tab_code, lower( nvl( ( SELECT d.BASE_TABLE_PK FROM hls_doc_layout_tab d WHERE d.LAYOUT_CODE = t1.LAYOUT_CODE AND d.BASE_TABLE = t1.PARENT_TABLE AND d.ENABLED_FLAG = 'Y' and rownum=1 ), t1.BASE_TABLE_PK ) ) AS parent_base_table_pk, t1.TAB_TYPE AS tab_type, ( CASE WHEN ( t1.BASE_TABLE is null ) THEN 'N' WHEN ( t1.RECREATE_DS_FLAG = 'Y' ) THEN 'Y' ELSE ( CASE WHEN ( ( SELECT 1 FROM DUAL WHERE EXISTS ( SELECT 1 FROM hls_doc_layout_tab t WHERE ( ( t.LAYOUT_CODE = t1.LAYOUT_CODE ) AND ( t.BASE_TABLE = t1.BASE_TABLE ) AND ( t.TAB_SEQ < t1.TAB_SEQ ) AND ( t.ENABLED_FLAG = 'Y' ) ) ) ) = 1 ) THEN 'N' ELSE 'Y' END ) END ) AS parent_tab_code_flag, ( CASE nvl(t1.PARENT_TABLE,'N') WHEN 'N' THEN 'N' ELSE 'Y' END ) AS parent_table_flag, t1.REF_TAB_CODE AS ref_tab_code, t1.TAB_REF_SCREEN AS tab_ref_screen, ( CASE t1.SETUP_WIDTH WHEN 'MARGIN_WIDTH' THEN nvl( t1.MARGIN_WIDTH, 70 ) ELSE '' END ) AS margin_width, ( CASE t1.SETUP_WIDTH WHEN 'ABSOLUTE_WIDTH' THEN nvl( t1.WIDTH, 300 ) ELSE '' END ) AS width, ( CASE t1.SETUP_HEIGHT WHEN 'MARGIN_HEIGHT' THEN nvl( t1.MARGIN_HEIGHT, 70 ) ELSE '' END ) AS margin_height, ( CASE t1.SETUP_HEIGHT WHEN 'ABSOLUTE_HEIGHT' THEN nvl( t1.HEIGHT, 200 ) ELSE '' END ) AS height, t1.ATTACHMENT_TAB_GROUP AS attachment_tab_group, nvl( t1.QUERY_ONLY, 'N' ) AS query_only, ( CASE t1.FETCHALL WHEN 'Y' THEN 'true' ELSE 'false' END ) AS fetchall, t1.QUERY_TAB_CODE AS query_tab_code, ( SELECT lt.BASE_TABLE FROM hls_doc_layout_tab lt WHERE ( ( lt.LAYOUT_CODE = t1.LAYOUT_CODE ) AND ( lt.TAB_CODE = t1.QUERY_TAB_CODE ) ) ) AS query_base_table, t1.CHECK_BEFORE_DELETE_BM AS check_before_delete_bm, t1.CHECK_AFTER_SAVE_BM AS check_after_save_bm, t1.SWITCHCARD_VALUE AS switchcard_value, ( CASE
WHEN ( t1.ROOT_TREE_CODE = 'TENANT' ) THEN 'TENANT' WHEN ( ( t1.ROOT_TREE_CODE = 'GUARANTEE' ) AND ( ( t1.BASE_TABLE = 'PRJ_PROJECT_BP' ) OR ( t1.PARENT_TABLE = 'PRJ_PROJECT_BP' ) ) ) THEN 'GUARANTOR' WHEN ( ( t1.ROOT_TREE_CODE = 'ACT_CTRLER' ) AND ( ( t1.BASE_TABLE = 'PRJ_PROJECT_BP' ) OR ( t1.PARENT_TABLE = 'PRJ_PROJECT_BP' ) ) ) THEN 'GUARANTOR' END ) AS query_bp_category, t1.selected_flag FROM hls_doc_layout_tab t1
${leaf_default_where_sql}
AND t1.layout_code = #{layout_code} AND t1.enabled_flag = 'Y'
AND t1.tab_code = #{tab_code}
AND lower(t1.parent_table) = lower(#{parent_table})
AND t1.parent_tab_code = #{parent_tab_code}
AND t1.base_table is not null and t1.parent_table is null
ORDER BY t1.ENABLED_FLAG DESC, t1.TAB_SEQ ) tmp

SELECT t1.layout_code, t1.tab_code, (case when t1.parent_tab_code_flag = 'Y' then t1.tab_code else t1.parent_table_tab_code end) form_binder_tab_code, t1.tab_desc, t1.tab_seq, t1.tab_group, lower(t1.base_table) base_table, t1.query_source, t1.row_count, t1.column_count, t1.enabled_flag, t1.created_by, t1.creation_date, t1.last_updated_by, t1.last_update_date, t1.configurable, t1.field_width, t1.label_width, t1.margin_top, t1.box_width, t1.show_box, t1.parent_tab_code, lower(t1.parent_table) parent_table, t1.base_table_pk, t1.parent_table_tab_code, t1.parent_base_table_pk, t1.tab_type, t1.parent_tab_code_flag, t1.parent_table_flag, t1.tree_code, t1.ref_tab_code, t1.tab_ref_screen, t1.margin_width, t1.width, t1.margin_height, t1.height, t1.repeat_object, (case when t1.repeat_bindertarget_flag = 'Y' then #{bp_seq} else '' end) repeat_bp_seq, t1.parent_loaded_object, t1.attachment_tab_group, t1.root_tree_code, t1.repeat_bindname_object, ( SELECT p.project_name FROM prj_project p WHERE p.project_id = #{document_id} ) project_name, t1.query_bp_category, ( SELECT bc.description FROM hls_bp_category bc WHERE bc.bp_category = t1.query_bp_category ) query_bp_category_name, t1.query_only, t1.navbar, t1.fetchall, t1.check_before_delete_bm, t1.check_after_save_bm, t1.switchcard_value, t1.selected_flag FROM () t1
${leaf_default_where_sql}
and t1.layout_code= #{layout_code} and t1.enabled_flag='Y'
AND t1.tab_code = #{tab_code}
AND t1.parent_tab_code = #{parent_tab_code}
AND t1.parent_table = #{parent_table}
AND t1.tree_code=#{tree_code} or #{all_data_flag}='Y'
AND t1.root_tree_code=#{root_tree_code} or t1.parent_table= 'PRJ_PROJECT'
AND t1.base_table is not null and t1.parent_table is null

SELECT t1.config_id, s.layout_code, lower(nvl(s.column_name, 'DIV')) column_name, t1.data_type, t1.system_flag, nvl( t1.enabled_flag, 'N' ) enabled_flag, nvl( t1.display_flag, 'N' ) display_flag, t1.display_order, t1.prompt, ( CASE WHEN t1.input_mode = 'REQUIRED' THEN 'TRUE' ELSE 'FALSE' END ) required_input_mode, ( CASE WHEN #{maintain_type} = 'READONLY' OR lt.query_only = 'Y' THEN 'TRUE' ELSE ( CASE WHEN t1.input_mode = 'READONLY' THEN 'TRUE' ELSE 'FALSE' END ) END ) readonly_input_mode, ( CASE WHEN s.column_name IS NULL THEN 'DIV' WHEN s.column_name IS NOT NULL AND t1.validation_type IN ( 'COMBOBOX', 'LOV', 'TREE', 'LOV_D' ) THEN ( CASE WHEN t1.lov_return_vcode IS NULL OR t1.lov_return_vcode = 'N' THEN t1.validation_type ELSE concat( t1.validation_type, '_C' ) END ) ELSE t1.validation_type END ) validation_type, /*---------------------------------- start ------------------------------------*/ t1.validation_type v_type, nvl(t1.clob_validation_sql, t1.validation_sql) validation_sql, /*----------------------------------- end ------------------------------------*/
nvl(t1.precision_num, 2 ) preci, nvl(t1.zero_fill, 'FALSE') zero_fill, nvl(t1.allow_format, 'FALSE') allow_format, nvl(t1.allow_decimal, 'FALSE') allow_decimal, t1.percent,
t1.default_value d_value, s.tab_code t_code, t1.column_name c_name,
t1.upper_limit, t1.lower_limit, ( CASE WHEN t1.width IS NULL THEN nvl(lt.field_width, 150) ELSE t1.width END ) width, nvl(s.colspan,1) colspan, nvl(s.rowspan,1) rowspan, t1.key_field_flag, t1.alignment, nvl(t1.lov_return_vcode, 'N') lov_return_vcode, s.tab_code, nvl(t1.height, 100) height, t1.field_javascript, ( CASE WHEN #{lov_search_rule} = 'AUTOCOMPLETE' THEN 'true' ELSE 'false' END ) autocomplete, ( CASE WHEN #{lov_search_rule} = 'FETCHSINGLE' THEN 'true' ELSE 'false' END ) fetchsingle, t1.underline, t1.field_group, t1.base_tab_code, t1.ignore_required FROM hls_doc_layout_config t1 RIGHT JOIN hls_doc_layout_screen s ON t1.layout_code = s.layout_code AND t1.column_name = s.column_name AND t1.tab_code = s.tab_code AND t1.enabled_flag = 'Y', hls_doc_layout_tab lt
${leaf_default_where_sql}
AND s.tab_code = lt.tab_code AND s.layout_code = lt.layout_code
AND s.tab_code=#{tab_code}
AND s.layout_code = #{layout_code}
AND s.form_tab_code = #{form_tab_code}
AND s.grid_tab_code = #{grid_tab_code}
AND s.column_name = upper(#{column_name})
order by s.order_seq asc

select
      *
from
      hls_doc_layout_config t
where
      t.layout_code = #{layout_code}
  and t.tab_code = #{tab_code}
  and t.column_name = #{column_name}

SELECT t1.config_id, t1.layout_code, t1.tab_code, lower( t1.column_name ) column_name, t1.data_type, t1.system_flag, nvl( t1.enabled_flag, 'N' ) enabled_flag, nvl( t1.display_flag, 'N' ) display_flag, t1.display_order, t1.prompt, t1.input_mode, (case when t1.input_mode = 'REQUIRED' or t1.input_mode = 'REQUIRED_ONLY_ADD' then 'TRUE' else 'FALSE' end ) required_input_mode, ( CASE WHEN #{maintain_type} = 'READONLY' OR lt.query_only = 'Y' THEN 'TRUE' ELSE (case when t1.input_mode = 'READONLY' then 'TRUE' else 'FALSE' end ) END ) readonly_input_mode, ( CASE WHEN t1.validation_type IN ( 'COMBOBOX', 'LOV', 'TREE', 'LOV_D' ) THEN ( case when t1.lov_return_vcode is null or t1.lov_return_vcode = 'N' then t1.validation_type else concat(t1.validation_type, '_C') end ) ELSE t1.validation_type END ) validation_type, t1.validation_type v_type, nvl(t1.clob_validation_sql, t1.validation_sql ) validation_sql, nvl(t1.precision_num, 2) preci, nvl(t1.zero_fill, 'FALSE') zero_fill, nvl(t1.allow_format, 'FALSE') allow_format, nvl(t1.allow_decimal, 'FALSE') allow_decimal, t1.percent, t1.default_value d_value, t1.tab_code t_code, t1.column_name c_name, t1.upper_limit, t1.lower_limit, ( CASE WHEN lt.tab_type = 'FIELDBOXCOLUMN' THEN nvl(t1.width, lt.field_width) ELSE nvl(t1.width, 120) END ) width, t1.key_field_flag, nvl(t1.alignment, 'center') alignment, nvl(t1.lov_return_vcode, 'N') lov_return_vcode, t1.copy_from_parent_tab, t1.height, ( CASE WHEN #{lov_search_rule} = 'AUTOCOMPLETE' THEN 'true' ELSE 'false' END ) autocomplete, ( CASE WHEN #{lov_search_rule} = 'FETCHSINGLE' THEN 'true' ELSE 'false' END ) fetchsingle, ( CASE WHEN t1.footerrenderer = 'Y' then 'sumFunction' ELSE '' END ) footerrenderer, ( CASE WHEN t1.validation_type IN ('TEXTFIELD', 'TEXTAREA') THEN 'true' ELSE 'false' END ) sys_grid_show_title, lower(t1.lov_cascade_para1) lov_cascade_para1, lower(t1.lov_cascade_para2) lov_cascade_para2, lower(t1.lov_cascade_para3) lov_cascade_para3, t1.field_javascript, t1.underline, t1.field_group, lt.query_only, t1.switchcard_tab_code, t1.base_tab_code, t1.ignore_required, nvl(t1.field_bak_flag, 'N') field_bak_flag FROM hls_doc_layout_config t1, hls_doc_layout_tab lt
${leaf_default_where_sql}
AND t1.layout_code = lt.layout_code AND t1.tab_code = lt.tab_code
AND t1.tab_code=#{tab_code}
AND t1.layout_code = #{layout_code}
AND t1.enabled_flag = #{enabled_flag}
AND t1.display_flag = #{display_flag}
AND t1.column_name = upper(#{column_name})
AND t1.switchcard_tab_code = upper(#{switchcard_tab_code})
ORDER BY t1.display_order

SELECT
*
FROM
hls_doc_layout_button t1


        ${leaf_default_where_sql}

    and t1.function_code=#{function_code}
    and t1.enabled_flag='Y'

        t1.button_code = #{button_code}


order by t1.display_order

SELECT lov_config_id, config_id, lov_col_for_query, lov_col_for_display, lov_col_display_width, lov_data_type, lov_col_prompt, lov_col_sequence, lov_col_name FROM hls_doc_layout_config_lov t1
${leaf_default_where_sql}
AND t1.config_id=#{config_id}
order by t1.lov_col_sequence

SELECT
